import json
import yaml
import sys

def extract_depends_on_resources(template_content):
    try:
        template = json.loads(template_content)
    except json.JSONDecodeError:
        try:
            template = yaml.safe_load(template_content)
        except yaml.YAMLError:
            return []

    if not isinstance(template, dict):
        return []

    resources = template.get('Resources', {})

    if not isinstance(resources, dict):
        return []

    depends_on_resources = []

    for logical_id, resource in resources.items():
        if isinstance(resource, dict) and 'DependsOn' in resource:
            depends_on_resources.append(logical_id)

    return depends_on_resources


if __name__ == "__main__":
    if len(sys.argv) > 1:
        template_file = sys.argv[1]
        with open(template_file, 'r') as f:
            template_content = f.read()
    else:
        template_content = sys.stdin.read()

    result = extract_depends_on_resources(template_content)
    print(json.dumps(result, indent=2))
